class Solution {
  // number of (s, e), 1 <= s <= p, 1 <= e <= q, s + e <= k + 1
  private static long count(long p, long q, long k) {
    long K = k + 1, m = Math.min(p, k);
    long s1 = Math.min(m, Math.max(0, K - q));
    return q * s1 + (m - s1) * K - (m * (m + 1) / 2 - s1 * (s1 + 1) / 2);
  }

  public long minMaxSubarraySum(int[] nums, int k) {
    int n = nums.length;
    int[] left = new int[n], right = new int[n], stack = new int[n];
    long total = 0;
    for (int pass = 0; pass < 2; pass++) {
      int sp = 0;
      for (int i = 0; i < n; i++) {
        while (sp > 0
            && (pass == 0 ? nums[stack[sp - 1]] < nums[i] : nums[stack[sp - 1]] > nums[i])) sp--;
        left[i] = sp == 0 ? -1 : stack[sp - 1];
        stack[sp++] = i;
      }
      sp = 0;
      for (int i = n - 1; i >= 0; i--) {
        while (sp > 0
            && (pass == 0 ? nums[stack[sp - 1]] <= nums[i] : nums[stack[sp - 1]] >= nums[i])) sp--;
        right[i] = sp == 0 ? n : stack[sp - 1];
        stack[sp++] = i;
      }
      for (int i = 0; i < n; i++) total += (long) nums[i] * count(i - left[i], right[i] - i, k);
    }
    return total;
  }
}
